      {/* ── Zoho Cliq Notification sub-modal ─────────────────────────── */}
      <Modal
        isOpen={zohoOpen}
        title="Zoho Cliq Notification"
        onClose={handleZohoCancel}
        onCancel={handleZohoCancel}
        onSave={handleZohoDone}
        cancelLabel="Cancel"
        saveLabel="Done"
